def _fallbacks_for(config: pytest.Config) -> Mapping[str, str]:
    if config.getoption("--inject-gpu-engine") == "spmd":
        # An SPMD execution mismatch is more specific than an inherited
        # in-memory fallback.  Remove those base entries before validating
        # effective-map disjointness below.
        return {
            nodeid: reason
            for nodeid, reason in (
                dict(CPU_FALLBACKS) | dict(SPMD_CPU_FALLBACKS)
            ).items()
            if nodeid not in SPMD_EXPECTED_FAILURES
        }
    return CPU_FALLBACKS


def _expected_failures_for(config: pytest.Config) -> Mapping[str, str]:
    if config.getoption("--inject-gpu-engine") == "spmd":
        return dict(EXPECTED_FAILURES) | dict(SPMD_EXPECTED_FAILURES)
    return EXPECTED_FAILURES


def _skips_for(config: pytest.Config) -> Mapping[str, str]:
    if config.getoption("--inject-gpu-engine") != "spmd":
        return TESTS_TO_SKIP
    skips = dict(TESTS_TO_SKIP) | dict(STREAMING_ENGINE_TESTS_TO_SKIP)
    if config.getoption("--inject-gpu-engine-blocksize") == "small":
        return skips | dict(STREAMING_ENGINE_TESTS_TO_SKIP_SMALL_BLOCKSIZE)
    return skips


def _validate_exception_lists(config: pytest.Config, items: list[pytest.Item]) -> None:
    """Reject stale or contradictory versioned GPU-execution exceptions."""
    collected = {item.nodeid for item in items}
    fallback = _fallbacks_for(config)
    expected = _expected_failures_for(config)
    overlap = sorted(fallback.keys() & expected.keys())
    if overlap:
        raise pytest.UsageError(
            "Tests cannot be both CPU-fallback and expected-failure:\n  "
            + "\n  ".join(overlap)
        )
    stale = sorted((fallback.keys() | expected.keys()) - collected)
    if stale:
        raise pytest.UsageError(
            "Stale cudf-polars GPU exception node IDs:\n  " + "\n  ".join(stale)
        )


@pytest.hookimpl(trylast=True)
def pytest_collection_modifyitems(
    session: pytest.Session, config: pytest.Config, items: list[pytest.Item]
) -> None:
    """Apply versioned GPU exceptions to the default strict policy."""
    _validate_exception_lists(config, items)
    num_shards = config.getoption("cudf_polars_num_shards")
    if num_shards > 1:
        shard_id = config.getoption("cudf_polars_shard_id")
        items[:], deselected = partition_items_by_shard(items, shard_id, num_shards)
        if deselected:
            config.hook.pytest_deselected(items=deselected)
    skips = _skips_for(config)
    expected_failures = _expected_failures_for(config)
    for item in items:
        if (reason := skips.get(item.nodeid)) is not None:
            item.add_marker(pytest.mark.skip(reason=reason))
        elif (reason := expected_failures.get(item.nodeid)) is not None:
            item.add_marker(pytest.mark.xfail(reason=reason))
